<?php require 'config.php'; require 'lib.php'; need_login(true); track_user(); csrf_check();
function can_lose_admin($id){ $q=db()->prepare('SELECT role FROM users WHERE id=?'); $q->execute([$id]); $t=$q->fetch(); if(!$t||$t['role']!=='admin') return true; $n=db()->prepare("SELECT COUNT(*) FROM users WHERE role='admin' AND disabled=0 AND id<>?"); $n->execute([$id]); return (int)$n->fetchColumn()>0; }
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??''; $uid=(int)($_POST['id']??0); $me=(int)$_SESSION['u']['id']; $lock=t('Du kan inte ta bort den sista aktiva administratören.','You cannot remove the last active administrator.');
 if($a==='add'&&strlen($_POST['p'])>=8) try{ db()->prepare('INSERT INTO users(username,email,password_hash,role,lang) VALUES(?,?,?,?,?)')->execute([trim($_POST['u']),trim($_POST['e']),password_hash($_POST['p'],PASSWORD_DEFAULT),$_POST['r']==='admin'?'admin':'user','en']); applog('info','auth','User created: '.trim($_POST['u']).' ('.($_POST['r']==='admin'?'admin':'user').')'); }catch(Exception $e){}
 if($a==='del'){ if($uid===$me) $_SESSION['flash']=t('Du kan inte ta bort dig själv.','You cannot delete yourself.'); elseif(!can_lose_admin($uid)) $_SESSION['flash']=$lock; else { $un=db()->prepare('SELECT username FROM users WHERE id=?'); $un->execute([$uid]); $un=$un->fetchColumn(); db()->prepare('DELETE FROM users WHERE id=?')->execute([$uid]); applog('warning','auth','User deleted: '.$un); } }
 if($a==='pw'){ if(strlen($_POST['p']??'')>=8){ db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['p'],PASSWORD_DEFAULT),$uid]); $_SESSION['flash']=t('Lösenordet ändrades.','Password changed.'); applog('info','auth','Password changed for user id '.$uid); } else $_SESSION['flash']=t('Lösenordet måste vara minst 8 tecken.','The password must be at least 8 characters.'); }
 if($a==='role'&&$uid===$me) $_SESSION['flash']=t('Du kan inte ändra din egen roll.','You cannot change your own role.');
 elseif($a==='role'){ $r=($_POST['r']??'')==='admin'?'admin':'user'; if($r==='user'&&!can_lose_admin($uid)) $_SESSION['flash']=$lock; else { db()->prepare('UPDATE users SET role=? WHERE id=?')->execute([$r,$uid]); $_SESSION['flash']=t('Rollen ändrades.','Role changed.'); applog('info','auth','Role changed for user id '.$uid.' → '.$r); } }
 if($a==='unlock'){ try{ db()->prepare('UPDATE users SET locked_until=NULL WHERE id=?')->execute([$uid]); db()->prepare('DELETE FROM login_fail WHERE user_id=?')->execute([$uid]); }catch(Throwable $e){} $_SESSION['flash']=t('Kontot är upplåst.','Account unlocked.'); applog('info','auth','Account unlocked, id '.$uid); }
 if($a==='totp_reset'){ try{ db()->prepare('UPDATE users SET totp_secret=NULL,totp_enabled=0,totp_recovery=NULL,totp_last=NULL WHERE id=?')->execute([$uid]); db()->prepare('DELETE FROM user_passkeys WHERE user_id=?')->execute([$uid]); td_clear($uid); }catch(Throwable $e){} $_SESSION['flash']=t('Tvåstegsverifieringen återställdes.','Two-step verification was reset.'); applog('warning','auth','2FA reset by admin for user id '.$uid); }
 if($a==='toggle'){ $q=db()->prepare('SELECT disabled FROM users WHERE id=?'); $q->execute([$uid]); $d=$q->fetchColumn();
  if($uid===$me) $_SESSION['flash']=t('Du kan inte inaktivera dig själv.','You cannot disable yourself.'); elseif($d==0&&!can_lose_admin($uid)) $_SESSION['flash']=$lock; else { db()->prepare('UPDATE users SET disabled=1-disabled,logged_in=0 WHERE id=?')->execute([$uid]); applog('info','auth','User enabled/disabled, id '.$uid); } }
 header('Location: users.php');exit; }
top(t('Användare','Users')); flash(); ?>
<h2><?= t('Inställningar','Settings') ?></h2>
<?php settings_tabs('users'); ?>
<form method="post" class="card inline"><?= csrf_field() ?><input type="hidden" name="a" value="add">
<input name="u" placeholder="<?= t('Användarnamn','Username') ?>" required><input name="e" type="email" placeholder="<?= t('E-post (för glömt lösenord)','Email (for password reset)') ?>"><input name="p" type="password" placeholder="<?= t('Lösenord (min 8)','Password (min 8)') ?>" required minlength="8">
<select name="r"><option value="user"><?= t('Användare (endast läsa)','User (view only)') ?></option><option value="admin">Admin</option></select><button class="btn"><?= t('Lägg till','Add') ?></button></form>
<table class="card"><tr><th><?= t('Namn','Name') ?></th><th><?= t('E-post','Email') ?></th><th><?= t('Roll','Role') ?></th><th>Status</th><th>2FA</th><th><?= t('Senast inloggad','Last login') ?></th><th><?= t('Senast aktiv','Last active') ?></th><th></th></tr>
<?php foreach(db()->query('SELECT *,IFNULL(logged_in=1 AND last_seen>NOW()-INTERVAL 5 MINUTE,0) AS online,(SELECT COUNT(*) FROM user_passkeys p WHERE p.user_id=users.id) AS pks,IFNULL(locked_until>NOW(),0) AS locked,TIMESTAMPDIFF(MINUTE,NOW(),locked_until)+1 AS lmin FROM users ORDER BY username') as $u): $lck=!empty($u['locked']); $on=(int)$u['online']===1; $dis=(int)$u['disabled']===1; $self=(int)$u['id']===(int)$_SESSION['u']['id']; ?>
<tr class="<?= $dis?'dim':'' ?>"><td><?= h($u['username']) ?></td><td><?= h($u['email']) ?></td>
<td><form method="post"><?= csrf_field() ?><input type="hidden" name="a" value="role"><input type="hidden" name="id" value="<?= $u['id'] ?>"><select name="r" onchange="this.form.submit()"<?= $self?' disabled title="'.h(t('Du kan inte ändra din egen roll','You cannot change your own role')).'"':'' ?>><option value="user"<?= $u['role']==='user'?' selected':'' ?>><?= t('Användare (endast läsa)','User (view only)') ?></option><option value="admin"<?= $u['role']==='admin'?' selected':'' ?>>Admin</option></select></form></td>
<td class="<?= $lck?'badt':($dis?'':($on?'okt':'mut')) ?>"><?= $lck?'🔒 '.t('Låst','Locked').' ('.(int)$u['lmin'].' min)':($dis?'⏸ '.t('Inaktiverad','Disabled'):($on?'● '.t('Inloggad','Online'):'○ '.t('Ej inloggad','Offline'))) ?></td><td><?= (!empty($u['totp_enabled'])||(int)$u['pks']>0)?'<span class="okt">✔ '.implode(' + ',array_filter([!empty($u['totp_enabled'])?'TOTP':'',(int)$u['pks']>0?'Passkey ('.(int)$u['pks'].')':''])).'</span>':'<span class="mut">–</span>' ?></td><td><?= $u['last_login']?h($u['last_login']):t('aldrig','never') ?></td><td><?= $on?t('nu','now'):($u['last_seen']?h($u['last_seen']):'–') ?></td>
<td class="inline"><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="a" value="pw"><input type="hidden" name="id" value="<?= $u['id'] ?>"><input name="p" type="password" minlength="8" required placeholder="<?= t('Nytt lösenord','New password') ?>" autocomplete="new-password" style="width:150px"><button class="btn sm"><?= t('Byt lösenord','Change password') ?></button></form>
<?php if(!empty($u['totp_enabled'])||(int)$u['pks']>0): ?><form method="post" onsubmit="return confirm('<?= h(t('Återställ tvåstegsverifiering för användaren?','Reset two-step verification for this user?')) ?>')"><?= csrf_field() ?><input type="hidden" name="a" value="totp_reset"><input type="hidden" name="id" value="<?= $u['id'] ?>"><button class="btn sm warn"><?= t('Återställ 2FA','Reset 2FA') ?></button></form><?php endif; ?>
<?php if($lck): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="a" value="unlock"><input type="hidden" name="id" value="<?= $u['id'] ?>"><button class="btn sm go"><?= t('Lås upp','Unlock') ?></button></form><?php endif; ?>
<?php if(!$self): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="a" value="toggle"><input type="hidden" name="id" value="<?= $u['id'] ?>"><button class="btn sm <?= $dis?'go':'warn' ?>"><?= $dis?t('Aktivera','Enable'):t('Inaktivera','Disable') ?></button></form>
<form method="post" onsubmit="return confirm('<?= t('Ta bort användaren?','Delete the user?') ?>')"><?= csrf_field() ?><input type="hidden" name="a" value="del"><input type="hidden" name="id" value="<?= $u['id'] ?>"><button class="btn danger sm"><?= t('Ta bort','Delete') ?></button></form><?php endif; ?></td></tr>
<?php endforeach; ?></table>
<?php bottom();
